contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 salt, uint256 delay) public {
        // Grant this contract the proposer role (its admin is TIMELOCK_ADMIN_ROLE,
        // which msg.sender = this contract holds from construction).
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        require(c.getRoleAdmin(c.PROPOSER_ROLE()) == c.TIMELOCK_ADMIN_ROLE());
        require(!c.isOperation(salt));
        require(delay >= c.getMinDelay());

        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);

        // Schedule the operation.
        c.schedule(address(this), 0, "", bytes32(0), salt, delay);

        // Pre-condition for a valid cancel: operation is pending.
        require(c.isOperationPending(id));
        require(c.getTimestamp(id) == block.timestamp + delay);

        // Cancelling an unknown id must revert.
        bool reverted;
        try c.cancel(bytes32(uint256(1))) { reverted = false; }
        catch { reverted = true; }

        // Cancel the pending operation (top-level state-changing call).
        c.cancel(id);

        assert(
            reverted &&
            c.getTimestamp(id) == 0 &&
            !c.isOperation(id) &&
            !c.isOperationPending(id)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 salt, uint256 delay) public {
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        require(!c.isOperation(salt));
        require(delay >= c.getMinDelay());

        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);

        bool lowDelayReverted;
        if (c.getMinDelay() > 0) {
            try c.schedule(address(this), 0, "", bytes32(0), salt, c.getMinDelay() - 1) {
                lowDelayReverted = false;
            } catch {
                lowDelayReverted = true;
            }
        } else {
            lowDelayReverted = true;
        }

        c.schedule(address(this), 0, "", bytes32(0), salt, delay);

        assert(
            lowDelayReverted &&
            c.getTimestamp(id) == block.timestamp + delay &&
            c.isOperationPending(id)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, bytes32 salt, uint256 delay) public {
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.grantRole(c.EXECUTOR_ROLE(), address(this));

        require(delay > 0);
        require(!c.isOperation(salt));

        bytes32 id = c.hashOperation(target, 0, "", bytes32(0), salt);

        c.schedule(target, 0, "", bytes32(0), salt, delay);

        bool execReverted;
        try c.execute(target, 0, "", bytes32(0), salt) {
            execReverted = false;
        } catch {
            execReverted = true;
        }

        assert(
            execReverted &&
            c.getTimestamp(id) > 0 &&
            c.isOperationPending(id) &&
            !c.isOperationDone(id) &&
            c.getTimestamp(id) > block.timestamp
        );
    }

    receive() external payable {}
}

